<?php
namespace Tests\Feature\Admin;use App\Enums\LeadStatus;use App\Models\Invoice;use App\Models\Lead;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AnalyticsParityTest extends TestCase{use RefreshDatabase;
public function test_admin_analytics_and_staff_performance_render_scoped_metrics():void{$admin=User::factory()->create(['role'=>'admin']);$sales=User::factory()->create(['role'=>'sales']);$lead=Lead::factory()->create(['assigned_to'=>$sales->id,'status'=>LeadStatus::CONFIRMED->value,'created_at'=>today()]);Invoice::factory()->create(['lead_id'=>$lead->id,'invoice_date'=>today(),'total_amount'=>1000,'payment_amount'=>400,'balance_amount'=>600]);$summary=app(\App\Services\AdminAnalyticsService::class)->summary(today()->subDays(30)->toDateString(),today()->toDateString());$this->assertEquals(1000,$summary['revenue']);$this->assertEquals(600,$summary['receivable']);$this->actingAs($admin)->get(route('admin.analytics.index'))->assertOk()->assertSee('Business performance');$this->get(route('admin.analytics.staff'))->assertOk()->assertSee($sales->name)->assertSee('100%');}
public function test_sales_manager_only_sees_team_performance():void{$manager=User::factory()->create(['role'=>'sales','is_manager'=>true]);$member=User::factory()->create(['role'=>'sales','is_manager'=>false]);$otherManager=User::factory()->create(['role'=>'sales','is_manager'=>true]);$this->actingAs($manager)->get(route('admin.analytics.staff'))->assertOk()->assertSee($member->name)->assertSee($manager->name)->assertDontSee($otherManager->name);}
public function test_csv_exports_are_authorized_and_contain_scoped_rows():void{$admin=User::factory()->create(['role'=>'admin']);Lead::factory()->create(['customer_name'=>'Export Traveller','created_at'=>today()]);$response=$this->actingAs($admin)->get(route('admin.exports.download',['type'=>'leads','from'=>today()->toDateString(),'to'=>today()->toDateString()]));$response->assertOk();$this->assertStringContainsString('Export Traveller',$response->streamedContent());$plain=User::factory()->create(['role'=>'marketing']);$this->actingAs($plain)->get(route('admin.exports.download',['type'=>'leads']))->assertForbidden();}
public function test_parity_audit_confirms_native_coverage_and_filament_removal_gate():void{$this->artisan('admin:parity-audit')->expectsOutputToContain('All required native route groups are present.')->assertSuccessful();$this->artisan('admin:parity-audit --strict')->expectsOutputToContain('No Filament routes remain; dependency removal gate is clear.')->assertSuccessful();}
}
